head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
scwin.strSch;
scwin.gEmpNo;
scwin.gAcptNo; // 접수번호
scwin.gFormUpclssCd; // 공시대분류
scwin.gRsnClsscd; // 사유분류코드
scwin.gMktId; // 시장구분

scwin.vScrenID = 'ULDSTF10002.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

// 부모창의 frame_head 데이타 셋팅하기
scwin.fn_setParamData = function() {
    /*
    		gFormUpclssCd = frame.Provider("../").dts_AcptProcs.NameString(1, 'FORM_UPCLSS_CD');
    		gRsnClsscd = frame.Provider("../").dts_AcptProcs.NameString(1, 'RSN_CLSS_CD');
    		gAcptNo = frame.Provider("../").dts_AcptProcs.NameString(1, 'ACPT_NO');
    		gMktId = frame.Provider("../").dts_AcptProcs.NameString(1, 'MKT_ID');
    */
    scwin.gFormUpclssCd = $c.frame.path("../../frame_head").dts_AcptProcs.getCellData(1, 'FORM_UPCLSS_CD');
    scwin.gRsnClsscd = $c.frame.path("../../frame_head").dts_AcptProcs.getCellData(1, 'RSN_CLSS_CD');
    scwin.gAcptNo = $c.frame.path("../../frame_head").dts_AcptProcs.getCellData(1, 'ACPT_NO');
    scwin.gMktId = $c.frame.path("../../frame_head").dts_AcptProcs.getCellData(1, 'MKT_ID');
    scwin.strSch = scwin.gRsnClsscd;
    scwin.gEmpNo = js_emp_no; // 세션정보 		

};


// 수정하기  
scwin.fn_ModifyDsclRsnClss = function() {
    var vTp = $c.stf.getObjectValue(cmb_DisclsRsnClss);
    if (vTp.length < 1) {
        $c.win.alert("사유분류를 선택하시오.");
        cmb_DisclsRsnClss.focus();
        return;
    }
    var vAnswer = confirm('사유분류를 변경하시겠습니까?');
    if (vAnswer == true) {
        trs_modify.Action = "/DisclosureStudy.do?method=modifyDisclosureReason&inputMessageId=DISCLSRSN_IN&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03 + "&ACPT_NO=" + scwin.gAcptNo;
        trs_modify.KeyName = "toinb_dataid4";
        trs_modify.KeyValue = "JSP(I:pInput=dts_procinfo)";
        trs_modify.Post();
    }
};
scwin.trs_modify_OnSuccess = async function() {
    $c.win.alert("성공적으로 저장되었습니다.");
    await $c.frame.CloseFrame();

    // 부모창의  frame_head를  reload 처리해야함
    $c.frame.path("../../frame_head").fn_HeadRead();
};
scwin.trs_modify_OnFail = function() {
    $c.win.alert('trs_modify.OnFail() :' + trs_modify.ErrorMsg);
};
scwin.btn_Cancle_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.dts_Rsnclss_OnLoadCompleted = function(rowcount) {
    // 초기1회 초기값으로 설정된 사유분류를 검색한다.
    if (scwin.strSch != "") {
        for (var i = 1; i <= dts_Rsnclss.getTotalRow(); i++) {
            if (scwin.strSch == dts_Rsnclss.getCellData(i, 1)) {
                dts_Rsnclss.setRowPosition(i, 0);
                break;
            }
        }
        scwin.strSch = "";
    }
};
scwin.dts_Rsnclss_OnLoadError = function() {
    $c.stf.alert_error(dts_Rsnclss);
};
scwin.btn_Save_onclick = function() {
    dts_procinfo.insertRow();
    dts_procinfo.setCellData(1, "ACPT_NO", scwin.gAcptNo);
    dts_procinfo.setCellData(1, "FORM_UPCLSS_CD", scwin.gFormUpclssCd);
    dts_procinfo.setCellData(1, "RSN_CLSS_CD", $c.cp.valueOfIndex(cmb_DisclsRsnClss, "VALUE", cmb_DisclsRsnClss.getSelectedIndex()));
    dts_procinfo.setCellData(1, "EMP_NO", scwin.gEmpNo);
    dts_procinfo.setCellData(1, "DISCLS_DUTY_TP_CD", js_duty_tp_cd);
    scwin.fn_ModifyDsclRsnClss();
};
scwin.gform_onload = function() {
    // 패널라운드 처리
    $c.libRoundPanel.PanelToGroupBox(panel_1);

    // 가우스헤더 셋팅
    dts_procinfo.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=DISCLSRSN_IN";
    dts_procinfo.reset();

    // 부모창의 데이타 셋팅하기
    scwin.fn_setParamData();

    // 대분류에 해당하는 사유분류리스트  셋팅
    dts_Rsnclss.DataID = "/CodeAction.do?method=listDisclsRsnclss&inputMessageId=FORMUPCLSS_IN&outputMessageId=CODE_OUT" + "&FOR=R&FORMUPCLSSCD=" + scwin.gFormUpclssCd;
    dts_Rsnclss.Reset();
};
